"""uv（pyproject.toml と uv.lock）で依存を管理しているかを、git 上のファイルだけを見て検査する"""

import json
import os
import re
import sys
from fnmatch import fnmatchcase
from pathlib import Path, PurePosixPath

sys.path.insert(0, str(Path(__file__).resolve().parents[1] / "_lib"))
import gha

# 対象を増やすときは style.yml の paths-filter の python にも追加する（フィルタから漏れると起動しない）
LEGACY_PATHSPECS = [
    ":(glob)**/*requirements*.txt",
    ":(glob)**/requirements/*.txt",
    ":(glob)**/setup.py",
    ":(glob)**/setup.cfg",
    ":(glob)**/Pipfile",
    ":(glob)**/Pipfile.lock",
    ":(glob)**/poetry.lock",
    ":(glob)**/pdm.lock",
]


def read_text(path: str) -> str:
    """読めないファイルは空として扱う"""
    try:
        return Path(path).read_text(encoding="utf-8", errors="replace")
    except OSError:
        return ""


def is_legacy(file: str, *, has_manifests: bool, has_sources: bool) -> bool:
    """pyproject.toml / uv.lock の代わりに依存を管理しているファイルか"""
    if fnmatchcase(file, "*requirements*.txt") or fnmatchcase(file, "*requirements/*.txt"):
        # requirements 系は依存管理として使われているものだけを対象にする
        # （pyproject.toml がある repo ではその隣にあるもの、無い repo は Python コードがあるときだけ）。
        # requirements/ に分けている場合は、その親を宣言の置き場所とみなす
        directory = PurePosixPath(file).parent
        if fnmatchcase(file, "*requirements/*.txt"):
            directory = directory.parent
        if has_manifests and not Path(directory, "pyproject.toml").exists():
            return False
        if not has_manifests and not has_sources:
            return False
        # uv export で書き出したものは配布用の成果物として許可する
        first_line = read_text(file).split("\n", 1)[0]
        return "autogenerated by uv" not in first_line
    if PurePosixPath(file).name in ("setup.py", "setup.cfg"):
        # 依存を宣言しない setup.py / setup.cfg は、ビルド定義（C 拡張等）や他ツールの設定として許可する
        return re.search(r"(install|setup)_requires", read_text(file)) is not None
    return True


def in_lock(project: str, rel: str) -> bool:
    """rel が project の uv.lock に記録されている（= workspace の member である）か"""
    lock = read_text(f"{project}/uv.lock")
    return any(f'{key} = "{rel}"' in lock for key in ("editable", "virtual", "directory"))


def main() -> None:
    status = 0
    has_manifests = bool(gha.git_z("ls-files", "--", ":(glob)**/pyproject.toml"))
    has_sources = bool(gha.git_z("ls-files", "--", ":(glob)**/*.py", ":(glob)**/*.pyi"))
    for file in gha.git_z("ls-files", "--", *LEGACY_PATHSPECS):
        if is_legacy(file, has_manifests=has_manifests, has_sources=has_sources):
            gha.error(
                f"{file} ではなく pyproject.toml と uv.lock で依存を管理してください"
                "（https://docs.astral.sh/uv/guides/migration/pip-to-project/）",
                file=file,
            )
            status = 1

    # 自分の uv.lock を持つか、祖先の lock に記録されていることを確認する。lock が最新かは依存関係の導入時に uv が判定する
    for item in json.loads(os.environ["PYPROJECTS"]):
        if not item["project"]:
            gha.error(
                "uv.lock がありません。uv lock を実行して uv.lock をコミットしてください"
                "（https://docs.astral.sh/uv/concepts/projects/layout/#the-lockfile）",
                file=item["path"],
            )
            status = 1
        elif item["rel"] != "." and not in_lock(item["project"], item["rel"]):
            gha.error(
                "uv.lock に含まれていません。uv lock を実行して uv.lock をコミットするか、workspace の members に追加してください"
                "（https://docs.astral.sh/uv/concepts/projects/workspaces/）",
                file=item["path"],
            )
            status = 1

    # どの uv.lock にも属さない import-linter の設定は、検査に使う環境を作れないため誰も検査できない
    for item in json.loads(os.environ["IMPORTLINTERS"]):
        if not item["project"]:
            gha.error(
                "import-linter の設定がどの uv.lock の配下にもないため検査できません。pyproject.toml と uv.lock で依存を管理してください"
                "（https://docs.astral.sh/uv/guides/migration/pip-to-project/）",
                file=item["path"],
            )
            status = 1
    sys.exit(status)


if __name__ == "__main__":
    main()
